mapper.select:
select payload from response_review where project_id=#{projectId}
    and json_unquote(json_extract(payload,'$.kind'))='deviation'
    and json_unquote(json_extract(payload,'$.status'))='待处理'
    and cast(json_unquote(json_extract(payload,'$.workVersion')) as unsigned)=#{workVersion}

mapper.update:
update response_review set payload=json_set(payload,'$.status','已取消','$.supersededByWorkVersion',#{workVersion})
where project_id=#{projectId} and json_unquote(json_extract(payload,'$.requirementId'))=#{requirementId}
    and json_unquote(json_extract(payload,'$.status')) not in ('已关闭','已取消')
